package com.littlemakers.village.nativeapp;
import android.content.Context;import android.graphics.Bitmap;import android.opengl.*;import android.view.*;import java.nio.*;import javax.microedition.khronos.opengles.GL10;import javax.microedition.khronos.egl.EGLConfig;import org.json.*;
/** Offline native GLES2 clay mesh: direct deformation, rotation, shading, saved geometry. */
final class ClaySurface extends GLSurfaceView implements GLSurfaceView.Renderer {
 private static final int ROWS=17,COLS=32;private final float[][]points=new float[ROWS*COLS][3];private final float[][]normals=new float[ROWS*COLS][3];private MaterialTexture materials;private FloatBuffer vertices;private int program,pos,normal,mvpU,modelU,colorU;private final float[]pv=new float[16];private float rotation=-20,lx,ly;String tool="Pull";private volatile int color=0xffbd5c75;private final float[]mvp=new float[16],view=new float[16],proj=new float[16],model=new float[16];
 ClaySurface(Context c){super(c);setEGLContextClientVersion(2);setPreserveEGLContextOnPause(true);reset();String state=c.getSharedPreferences("creative",0).getString("clay3d","");if(!state.isEmpty())try{JSONArray a=new JSONArray(state);for(int i=0;i<points.length;i++)for(int j=0;j<3;j++)points[i][j]=(float)a.getDouble(i*3+j);}catch(Exception ignored){}setRenderer(this);setRenderMode(RENDERMODE_WHEN_DIRTY);setContentDescription("Three-dimensional clay. Drag to sculpt. Select Rotate to view another side.");}
 synchronized void reset(){for(int r=0;r<ROWS;r++)for(int col=0;col<COLS;col++){double lat=Math.PI*r/(ROWS-1),lon=2*Math.PI*col/COLS;float[]p=points[r*COLS+col];p[0]=(float)(Math.sin(lat)*Math.cos(lon));p[1]=(float)Math.cos(lat);p[2]=(float)(Math.sin(lat)*Math.sin(lon));}}
 void tint(int c){color=c;requestRender();}void persist(){JSONArray a=new JSONArray();synchronized(this){for(float[]p:points)for(float f:p)a.put(Float.valueOf(f));}getContext().getSharedPreferences("creative",0).edit().putString("clay3d",a.toString()).apply();}
 private int shader(int kind,String source){int sh=GLES20.glCreateShader(kind);GLES20.glShaderSource(sh,source);GLES20.glCompileShader(sh);int[]ok={0};GLES20.glGetShaderiv(sh,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetShaderInfoLog(sh));return sh;}
 public void onSurfaceCreated(GL10 gl,EGLConfig config){ThemeManager theme=new ThemeManager(getContext());GLES20.glClearColor(android.graphics.Color.red(theme.surface)/255f,android.graphics.Color.green(theme.surface)/255f,android.graphics.Color.blue(theme.surface)/255f,1);GLES20.glEnable(GLES20.GL_DEPTH_TEST);String vs="uniform mat4 uMvp;uniform mat4 uModel;attribute vec3 aPosition;attribute vec3 aNormal;varying vec3 vNormal;varying vec3 vPosition;void main(){vNormal=mat3(uModel)*aNormal;vPosition=aPosition;gl_Position=uMvp*vec4(aPosition,1.);}";program=GLES20.glCreateProgram();int v=shader(GLES20.GL_VERTEX_SHADER,vs),f=shader(GLES20.GL_FRAGMENT_SHADER,MaterialTexture.fragment(false));GLES20.glAttachShader(program,v);GLES20.glAttachShader(program,f);GLES20.glLinkProgram(program);GLES20.glDeleteShader(v);GLES20.glDeleteShader(f);int[]ok={0};GLES20.glGetProgramiv(program,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetProgramInfoLog(program));pos=GLES20.glGetAttribLocation(program,"aPosition");normal=GLES20.glGetAttribLocation(program,"aNormal");mvpU=GLES20.glGetUniformLocation(program,"uMvp");modelU=GLES20.glGetUniformLocation(program,"uModel");colorU=GLES20.glGetUniformLocation(program,"uColor");materials=new MaterialTexture(getContext());materials.create(program);GLES20.glUniform1f(GLES20.glGetUniformLocation(program,"uMaterial"),3);}

 public void onSurfaceChanged(GL10 gl,int width,int height){GLES20.glViewport(0,0,width,height);Matrix.perspectiveM(proj,0,42,(float)width/height,.1f,20);Matrix.setLookAtM(view,0,0,0,4.6f,0,0,0,0,1,0);}
 private void triangle(int a,int b,int c){vertices.put(points[a]);vertices.put(normals[a]);vertices.put(points[b]);vertices.put(normals[b]);vertices.put(points[c]);vertices.put(normals[c]);}
 private synchronized void build(){SurfaceNormals.calculate(points,ROWS,COLS,normals);if(vertices==null)vertices=ByteBuffer.allocateDirect((ROWS-1)*COLS*6*6*4).order(ByteOrder.nativeOrder()).asFloatBuffer();vertices.position(0);for(int r=0;r<ROWS-1;r++)for(int c=0;c<COLS;c++){int next=(c+1)%COLS;triangle(r*COLS+c,(r+1)*COLS+c,(r+1)*COLS+next);triangle(r*COLS+c,(r+1)*COLS+next,r*COLS+next);}vertices.position(0);}
 public void onDrawFrame(GL10 gl){build();GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT|GLES20.GL_DEPTH_BUFFER_BIT);GLES20.glUseProgram(program);materials.bind();Matrix.setRotateM(model,0,rotation,0,1,0);Matrix.multiplyMM(pv,0,proj,0,view,0);Matrix.multiplyMM(mvp,0,pv,0,model,0);GLES20.glUniformMatrix4fv(mvpU,1,false,mvp,0);GLES20.glUniformMatrix4fv(modelU,1,false,model,0);GLES20.glUniform3f(colorU,android.graphics.Color.red(color)/255f,android.graphics.Color.green(color)/255f,android.graphics.Color.blue(color)/255f);GLES20.glEnableVertexAttribArray(pos);GLES20.glEnableVertexAttribArray(normal);vertices.position(0);GLES20.glVertexAttribPointer(pos,3,GLES20.GL_FLOAT,false,24,vertices);vertices.position(3);GLES20.glVertexAttribPointer(normal,3,GLES20.GL_FLOAT,false,24,vertices);GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,(ROWS-1)*COLS*6);}

 @Override public boolean onTouchEvent(android.view.MotionEvent e){float x=e.getX(),y=e.getY();if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lx=x;ly=y;getParent().requestDisallowInterceptTouchEvent(true);return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=(x-lx)*3/getWidth(),dy=-(y-ly)*3/getHeight();if(tool.equals("Rotate"))rotation+=dx*100;else synchronized(this){float targetX=(x/getWidth()-.5f)*3,targetY=(.5f-y/getHeight())*3;double angle=Math.toRadians(rotation);for(float[]p:points){float rx=(float)(p[0]*Math.cos(angle)+p[2]*Math.sin(angle)),rz=(float)(-p[0]*Math.sin(angle)+p[2]*Math.cos(angle));float dist=(float)Math.hypot(rx-targetX,p[1]-targetY),w=Math.max(0,1-dist/.85f);if(rz<-.15f)w=0;if(tool.equals("Pull")){p[0]+=dx*w*Math.cos(angle);p[2]+=dx*w*Math.sin(angle);p[1]+=dy*w;}else if(tool.equals("Flatten")){p[1]*=.995;p[0]*=1.002;p[2]*=1.002;}else {p[0]*=1.004;p[1]*=.998;p[2]*=.998;}for(int j=0;j<3;j++)p[j]=Math.max(-1.6f,Math.min(1.6f,p[j]));}}lx=x;ly=y;requestRender();}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);persist();performClick();}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}
